function siteOrder(a,b){const key=site=>{const host=domains[site];if(!host)return [normalize(site),0,normalize(site)];const parts=host.split('.');return [parts.slice(-2).join('.'),parts.length===2?0:1,host];};const x=key(a.site),y=key(b.site);return x[0].localeCompare(y[0],'pt-BR',{sensitivity:'base'})||x[1]-y[1]||x[2].localeCompare(y[2],'pt-BR')||a.site.localeCompare(b.site,'pt-BR');}
function rollup(facts){const total=Object.fromEntries(['gross','invalid','net','tax','spend','profit'].map(k=>[k,facts.reduce((s,f)=>s+n(f[k]),0)]));total.roi_gross=total.spend?total.gross/Math.abs(total.spend)-1:'';total.roi_net=total.spend?total.net/(Math.abs(total.spend)+Math.abs(total.tax))-1:'';return total;}
function inputCurrency(input,f){return input.metric==='gross'&&input.book==='principal'&&input.source===f.source?.gross?'USD':input.currency;}
function originGross(f){const keys=[...new Set(data.model.facts[f.id]?.gross||[])],amounts={};for(const key of keys){const input=data.model.inputs[key];if(!input)continue;const c=inputCurrency(input,f);amounts[c]=(amounts[c]||0)+n(input.value);}if(!keys.length){const a=data.additions.find(x=>x.id===f.id&&!x.kind);if(a)amounts[a.currency]=n(a.gross);}return amounts;}
