function countryBlocks(facts){const countries=[...new Set(facts.map(f=>f.country))];return countries.map(code=>{const subset=facts.filter(f=>f.country===code);const blocks=[...new Set(subset.map(f=>f.segment))].map(segment=>{const rows=subset.filter(f=>f.segment===segment).sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id));const raw=rows.map(originGross),currencies=[...new Set([...raw.flatMap(x=>Object.keys(x)),...rows.flatMap(f=>(data.model.facts[f.id]?.gross||[]).map(k=>data.model.inputs[k].currency))])].filter(c=>c!=='USD').sort();const total=rollup(rows);const financial=f=>[num(f.gross),num(f.invalid),num(f.net),num(f.tax),num(f.spend),num(f.profit,true),roi(f.roi_gross),roi(f.roi_net)];const headers=['Dia',...currencies.map(c=>'Gross '+c),'Gross '+currency,'Inválidos','Receita líquida','Impostos','Mídia','Lucro líquido','ROI gross','ROI net','Ações'];const body=rows.map((f,i)=>[esc(f.date.slice(8)+'/08'),...currencies.map(c=>raw[i][c]===undefined?'—':esc(fmt(raw[i][c],c))),...financial(f),`<button class="smallbutton" data-edit-fact="${esc(f.id)}">Editar dia</button>`]);body.push(['Total do bloco',...currencies.map(c=>esc(fmt(raw.reduce((s,r)=>s+n(r[c]),0),c))),...financial(total),'']);const meta=data.domain.segments.find(s=>s.id===segment);return `<div class="country-segment"><div class="segment-heading"><strong>${esc(meta?.name||selectedSite)}${segment.endsWith('complementar')?' · complementar':''}</strong><span>${esc([...new Set(rows.map(f=>managerLabel(f.manager)))].join(' · '))} · ${esc([...new Set(rows.map(f=>f.partner))].join(' · '))}</span></div>${table(headers,body,body.map((_,i)=>i===body.length-1?'subtotal':''))}<div class="block-scroll-note">Role a tabela para ver todos os dias e colunas. O total fica na última linha; Editar dia permanece à direita.</div></div>`;}).join('');return `<details class="country-block" data-country="${esc(code)}"><summary class="country-heading"><h2>${esc(selectedSite)} · ${esc(code)}</h2><span>${subset.length} registros · ${currency} <span class="country-toggle" aria-hidden="true"></span></span></summary>${blocks}</details>`;}).join('')||'<div class="empty">Nenhum dia corresponde aos filtros.</div>';}
function siteExpenseTotal(){return data.domain.segments.filter(s=>s.site===selectedSite).reduce((sum,s)=>sum+n(s.expenses),0);}
function siteConsolidation(facts){
 const headers=['País','Receita gross','Inválidos','Receita líquida','Impostos','Mídia','Lucro operacional','Despesas do site','Resultado após despesas','ROI gross','ROI net'];
 const financial=t=>[num(t.gross),num(t.invalid),num(t.net),num(t.tax),num(t.spend),num(t.profit,true)];
 const countries=[...new Set(facts.map(f=>f.country))],filtered=Boolean(country||manager||day),total=rollup(facts),expense=siteExpenseTotal();
 const rows=countries.map(c=>{const t=rollup(facts.filter(f=>f.country===c));return [`<button class="linkbutton country-link" data-jump-country="${esc(c)}">${esc(c)}</button>`,...financial(t),'<span title="Despesa mensal do site; não atribuída a um país">—</span>','—',roi(t.roi_gross),roi(t.roi_net)];});
 rows.push([filtered?'TOTAL DA SELEÇÃO':'TOTAL DO SITE',...financial(total),`<span data-expense-total>${num(expense)}</span>`,`<span data-after-expenses>${filtered?'—':num(total.profit+expense,true)}</span>`,roi(total.roi_gross),roi(total.roi_net)]);
 return panel('Consolidado · '+selectedSite,'Receitas, mídia e despesas no topo da análise.',table(headers,rows,rows.map((_,i)=>i===rows.length-1?'netrow':''))+'<div class="summary-note">Sem rateio por país: a coluna Despesas do site mostra o rateio mensal entre os ativos, uma única vez no total. Despesas da empresa e status dos sites recalculam o rateio e as remunerações vinculadas. '+(filtered?'Filtros afetam os valores operacionais, mas não a despesa mensal do domínio; resultado após despesas não é apresentado para uma seleção parcial. ':'Resultado após despesas = lucro operacional + despesa do site (dedução); mídia e impostos já estão no lucro operacional. ')+'Não inclui remunerações. ROI gross = gross ÷ mídia − 1; ROI net = receita líquida ÷ (mídia + impostos) − 1, com deduções absolutas. Role lateralmente para ver todas as colunas.</div>').replace('<section class="panel"','<section data-site-consolidation class="panel"').replace('<div class="scroll">','<div class="scroll" tabindex="0" role="region" aria-label="Consolidado: role para os lados">');
}
function managerResults(){
 const siteFacts=data.domain.facts.filter(f=>f.site===selectedSite),labels=new Set(siteFacts.map(f=>normalize(f.site).replace(/[^a-z0-9]/g,'')));
 const contributions=data.domain.managers.filter(m=>m.row<12&&labels.has(normalize(m.label).replace(/[^a-z0-9]/g,'')));
 if(!contributions.length)return '';
 return panel('Resultado atribuído aos gestores','Resultado mensal do site inteiro, sem recorte de país, gestor ou dia; vínculos preservados da origem.',table(['Gestor','Resultado atribuído $','Resultado atribuído R$'],contributions.map(m=>[esc(managerLabel(m.manager)),fmt(m.profit),fmt(n(m.profit)*n(data.fx),'BRL')]))+'<div class="summary-note">Não são pagamentos nem rateios novos. Despesas da empresa e status dos sites propagam o rateio para este resultado e a remuneração vinculada.</div>').replace('<section class="panel"','<section data-manager-results class="panel"');
}
const matchesSite=(site,q)=>normalize(site).includes(normalize(q))||normalize(domains[site]||'').includes(normalize(q));
let data,accountData={accounts:[],slots:[],candidates:[],revision:0},currentPeriod='2026-08',reloadSequence=0,switching=false,accountSearch='',csrf=null,view='overview',search='',country='',manager='',selectedSite='',currency='USD',pageIndex=0,day='',submitHandler=null,busy=false;
async function api(url,body){const r=await fetch(url,body===undefined?{}:{method:'POST',headers:{'Content-Type':'application/json',...(csrf?{'X-CSRF-Token':csrf}:{})},body:JSON.stringify(body)});if(r.status===401){location.replace('/login');throw Error('Sessão encerrada');}const d=await r.json();if(!r.ok)throw Error(d.error||'Não foi possível concluir.');return d;}
function message(t,error=false){$('#message').textContent=t;$('#message').classList.toggle('error',error);}
const monthLabel=()=>data?.period?.label||'Agosto 2026';
async function reload(period=currentPeriod){const seq=++reloadSequence;const [next,accounts,periods]=await Promise.all([api('/api/workspace?period='+period),api('/api/ad-accounts?period='+period),api('/api/periods')]);if(seq!==reloadSequence)return;const changed=currentPeriod!==period;data=next;accountData=accounts;currentPeriod=period;if(changed){selectedSite='';search='';country='';manager='';day='';}$('#period').innerHTML=periods.map(p=>`<option value="${esc(p.id)}" ${p.id===period?'selected':''}>${esc(p.label)}</option>`).join('');$('#sync').textContent='Dados carregados';render();}
async function writable(){if(data.id==='baseline'){await api('/api/workspace/open',{period:currentPeriod});await reload();}return data.id;}
async function save(path,body){if($('#editor').open&&$('#editor').dataset.period!==currentPeriod)throw Error('O mês mudou; reabra o formulário.');const id=await writable();const before=data.revision;await api(`/api/scenarios/${id}/${path}`,{...body,period:currentPeriod,revision:before});await reload();if(data.revision<=before)throw Error('Gravação sem confirmação. Recarregue antes de repetir.');message('Alteração salva. Resultados recalculados e conferidos. A planilha foi preservada.');}
function num(v,profit=false){return `<span class="number ${n(v)<0?'negative':profit&&n(v)>0?'positive':''}">${esc(fmt(n(v)*(currency==='BRL'?n(data.fx):1),currency))}</span>`;}
function table(headers,rows,classes=[]){return `<div class="scroll"><table><thead><tr>${headers.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${rows.map((r,i)=>`<tr class="${classes[i]||''}">${r.map(x=>`<td>${x}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;}
function panel(title,subtitle,body,action=''){return `<section class="panel"><div class="panelhead"><div><h2>${esc(title)}</h2>${subtitle?`<p>${esc(subtitle)}</p>`:''}</div>${action}</div>${body}</section>`;}
function cards(items){return '<div class="cards">'+items.map(([label,usd,brl,note,emphasis])=>`<div class="card ${emphasis?'emphasis':''}"><small>${esc(label)}</small><strong>${usd===null||usd===''?'—':esc(fmt(usd))}</strong><p>${brl===null||brl===''?'—':esc(fmt(brl,'BRL'))}${note?`<br>${esc(note)}`:''}</p></div>`).join('')+'</div>';}
function siteGroups(facts=data.domain.facts){const groups=new Map();for(const f of facts){let g=groups.get(f.site);if(!g){g={site:f.site,status:(data.sites||[]).find(s=>s.name===f.site)?.status||f.status,countries:new Set(),partners:new Set(),managers:new Set(),gross:0,net:0,tax:0,spend:0,profit:0,invalid:0};groups.set(f.site,g);}for(const k of ['gross','net','tax','spend','profit','invalid'])g[k]+=n(f[k]);g.countries.add(f.country);g.partners.add(f.partner);if(f.manager)for(const label of managerTokens(f.manager))g.managers.add(label);}return [...groups.values()].sort(siteOrder);}
function reviewStatus(e){return normalize(e.status||'').trim()==='conferido'?'Conferido':normalize(e.status||'').trim()==='a conferir'?'A conferir':e.status||'A conferir';}
function reviewDate(value){return /^\d{4}-\d{2}-\d{2}$/.test(value||'')?value.split('-').reverse().join('/'):'—';}
function reviewBadge(e){const status=reviewStatus(e);return `<span class="pill ${status==='Conferido'?'good':'warn'}">${esc(status)}</span>`;}
function summaryExpenses(category){const rows=data.domain.expenses.filter(e=>e.category===category&&e.label&&!e.archived);const usd=rows.reduce((s,e)=>s+n(e.usd),0),brl=rows.reduce((s,e)=>s+n(e.brl),0);const body=table([category==='company'?'Despesa Tipo':'Gestor / funcionário','Valor $','Valor R$','Status','Data da conferência'],rows.map(e=>[esc(e.label),esc(fmt(Math.abs(n(e.usd)))),esc(fmt(Math.abs(n(e.brl)),'BRL')),reviewBadge(e),esc(reviewDate(e.checked_on))]).concat([['TOTAL',esc(fmt(Math.abs(usd))),esc(fmt(Math.abs(brl),'BRL')),'','']]),rows.map(()=> '').concat(['subtotal']));return `<div data-summary-expenses="${category}">${panel(category==='company'?'Despesas da empresa':'Despesas dos funcionários',monthLabel()+' · somente visualização · edição no Administrativo',body+'<div class="block-scroll-note">Role dentro da tabela para ver todos os lançamentos. Em telas menores, deslize para os lados para consultar valores, status e data da conferência.</div>')}</div>`;}
function summaryRates(){
 const labels={'F1 → Caixa J2':'USD/BRL · líquido','H1':'USD/CAD · Rede1','I1':'GBP/USD · YMonetize inativo','J1':'Inválidos · ActiveView','K1':'Inválidos · YMonetize inativo','L1':'Inválidos · JBF','EN82':'Inválidos · M2'};
 return `<section class="quote-strip" aria-label="Cotações e inválidos estimados"><div class="quote-strip-heading">Cotações e inválidos <small>Estimados até a liquidação · ↔ role para ver todos</small></div><div class="quote-strip-scroll" tabindex="0" role="region" aria-label="Cotações: role para os lados">${(data.rates||[]).filter(r=>r.type==='fx'||r.type==='invalid').map(r=>`<div class="quote-item" title="${esc(r.label)}"><span>${esc(labels[r.source]||r.label)}</span><strong>${esc(r.type==='invalid'?percent(r.value):dec(r.value))}</strong><small class="${r.status==='confirmed'?'confirmed':''}">${r.status==='confirmed'?'Confirmado':'Estimado · provisório'}</small></div>`).join('')}</div></section>`;
}
function countryOverview(){
 const facts=data.domain.facts,countries=[...new Set(facts.map(f=>f.country))].sort();
 const dual=(v,profit=false)=>`<span class="number ${n(v)<0?'negative':profit&&n(v)>0?'positive':''}">${v===null?'—':esc(fmt(v))}</span><span class="subline">${esc(fmt(n(v)*n(data.fx),'BRL'))}</span>`;
 const financial=t=>[dual(t.gross),dual(t.invalid),dual(t.net),dual(t.tax),dual(t.spend),dual(t.profit,true),roi(t.roi_gross),roi(t.roi_net)];
 const rows=countries.map(c=>[`<span data-summary-country="${esc(c)}">${esc(c)}</span>`,...financial(rollup(facts.filter(f=>f.country===c)))]);
 rows.push(['TOTAL OPERACIONAL',...financial(rollup(facts))]);
 return panel('Resumo por país','Todos os sites reunidos · USD e BRL · antes das despesas da empresa e de funcionários.',table(['País','Receita gross','Inválidos','Receita líquida','Impostos','Mídia','Lucro operacional','ROI gross','ROI net'],rows,rows.map((_,i)=>i===rows.length-1?'subtotal':''))+'<div class="block-scroll-note">Sem rateio de despesas gerais por país. Role lateralmente para consultar todas as colunas.</div>').replace('<section class="panel"','<section data-country-summary class="panel"').replace('<div class="scroll">','<div class="scroll" tabindex="0" role="region" aria-label="Resumo por país: role para os lados">');
}
function overview(){const c=data.domain.cash,fx=n(data.fx),projection=data.domain.projection||{state:'closed',half_usd:c.half_usd,half_brl:c.half_brl},estimateNote=projection.state==='closed'?'Período encerrado · sem extrapolação':projection.state==='planned'?'Período futuro · sem projeção realizada':'Projeção pelos dias completos; despesas mensais não são multiplicadas';const share=n(c.net)-n(c.gross)-n(c.invalid);const rows=[['Receita gross',n(c.gross),''],['Inválidos',n(c.invalid),''],['Rev share',share,''],['Receita',n(c.gross)+share,'subtotal'],['Impostos',n(c.tax),''],['Despesas da empresa',n(c.company_expenses),''],['Despesas dos funcionários',n(c.personnel),''],['Gastos com mídia',n(c.spend),''],['Resultado líquido total',n(c.profit),'subtotal'],['Líquido net · participação 50%',n(c.half_usd),'netrow'],['Estimativa do mês · 50%',projection.half_usd===null?null:n(projection.half_usd),'estimate']];
const composition=panel('Composição financeira','Receitas, deduções e resultado de '+monthLabel(),table(['Componente','Valor $','Valor R$'],rows.map(([l,v])=>[esc(l),`<span class="${v<0?'negative':''}">${v===null?'—':esc(fmt(v))}</span>`,`<span class="${v<0?'negative':''}">${v===null?'—':esc(fmt(v*fx,'BRL'))}</span>`]),rows.map(x=>x[2]))+'<div class="summary-note">A receita acima desconta o rev share. Inválidos são deduzidos na linha própria, sem duplicação. A participação de 50% corresponde ao fechamento do Caixa Sintético. Câmbio e inválidos podem ser ajustados até a liquidação. A estimativa usa o calendário do mês selecionado; períodos futuros não recebem resultados de agosto.</div>');
const top=siteGroups().sort((a,b)=>b.gross-a.gross).slice(0,6);const max=Math.max(1,...top.map(x=>x.gross));const ranking=panel('Sites em destaque','Maiores receitas no mês',`<div class="panelbody barlist">${top.map(x=>`<div class="baritem"><button class="linkbutton" data-site="${esc(x.site)}">${esc(x.site)}</button><span>${esc(fmt(x.gross))}</span><div class="track"><span data-width="${x.gross/max*100}"></span></div></div>`).join('')}</div><div class="tablefooter"><span>Receita bruta · USD</span><button class="textbutton" data-view="movement">Ver todos os sites →</button></div>`);
return summaryRates()+cards([['Receita gross',c.gross,n(c.gross)*fx,'Antes das deduções'],['Gastos com mídia',Math.abs(n(c.spend)),Math.abs(n(c.spend))*fx,'Facebook e Google'],['Líquido net · 50%',c.half_usd,c.half_brl,'Participação no resultado',true],['Estimativa do mês · 50%',projection.half_usd,projection.half_brl,estimateNote]])+countryOverview()+`<div class="grid-two"><div>${composition}</div><div>${ranking}${panel('Sua rotina em um lugar','Consulte e atualize sem percorrer vários menus',`<div class="panelbody"><button data-view="movement">Abrir movimento do mês →</button><div class="rule-note">Busque o domínio, abra os dias e edite as receitas e as contas de anúncio. Os totais e as remunerações são recalculados.</div></div>`)}</div></div>`+`<div class="grid-two summary-expenses">${summaryExpenses('company')}${summaryExpenses('personnel')}</div>`;}
function filteredFacts(){return data.domain.facts.filter(f=>(!selectedSite||f.site===selectedSite)&&(!country||f.country===country)&&(!manager||managerTokens(f.manager).includes(manager)||managerLabel(f.manager)===manager)&&(!day||f.date===day));}
function options(values,current,empty){return `<option value="">${esc(empty)}</option>`+[...new Set(values)].sort().map(v=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(v)}</option>`).join('');}
function movement(){const facts=filteredFacts();const all=data.domain.facts;const controls=`<div class="filters"><div class="search"><input id="siteSearch" aria-label="Buscar domínio" placeholder="Buscar domínio ou nome do site…" value="${esc(search)}"></div><select id="countryFilter" aria-label="Filtrar país">${options(all.map(f=>f.country),country,'Todos os países')}</select><select id="managerFilter" aria-label="Filtrar gestor">${options(all.flatMap(f=>managerTokens(f.manager)),manager,'Todos os gestores')}</select>${selectedSite?`<input id="dayFilter" type="date" aria-label="Filtrar dia" min="${esc(currentPeriod)}-01" max="${esc(currentPeriod)}-${data.period?.days||31}" value="${esc(day)}">`:''}<div class="segmented"><button data-currency="USD" class="${currency==='USD'?'selected':''}">$</button><button data-currency="BRL" class="${currency==='BRL'?'selected':''}">R$</button></div></div>`;
const groups=siteGroups(facts).filter(g=>matchesSite(g.site,search)||normalize([...g.partners].join(' ')).includes(normalize(search)));
const siteTable=list=>list.length?table(['Domínio / site','Países','Gestor','Receita gross','Receita líquida','Mídia','Resultado','Ações'],list.map(g=>[`<button class="linkbutton" data-site="${esc(g.site)}">${esc(domains[g.site]||g.site)}</button><span class="subline">${esc(g.site)} · ${esc([...g.partners].join(' · '))}</span>`,esc([...g.countries].join(' · ')),esc([...g.managers].join(' · ')),num(g.gross),num(g.net),num(g.spend),num(g.profit),`<button class="smallbutton" data-site="${esc(g.site)}">Abrir →</button>`])):'<div class="empty">Nenhum site neste grupo com os filtros atuais.</div>';
let body='';if(!selectedSite){body=['ATIVO','INATIVO',...(groups.some(g=>!['ATIVO','INATIVO'].includes(g.status))?['PENDENTE']:[])].map(status=>{const list=groups.filter(g=>status==='PENDENTE'?!['ATIVO','INATIVO'].includes(g.status):g.status===status);return `<section class="site-status-group" data-site-status="${status}"><h3>${status==='ATIVO'?'Sites Ativos':status==='INATIVO'?'Sites Inativos':'Status a conferir'} <small>${list.length} sites</small></h3>${siteTable(list)}</section>`;}).join('');body+=`<div class="tablefooter"><span>${groups.length} sites · status do mês selecionado, não inferido pela receita</span><span>Abra um site para consultar e editar os dias.</span></div>`;}
else{body=countryBlocks(facts);}
let result=(selectedSite?`<button id="backSites" class="textbutton back">← Todos os sites</button>`:'')+panel(selectedSite||'Seus sites','Receitas e gastos juntos. Edite as entradas; o sistema calcula os resultados.',controls+'<div id="movementRows">'+body+'</div>',`<button id="newEntry" class="secondary">+ Lançamento extra</button>`);
if(selectedSite){const t=siteGroups(facts)[0]||{};result=siteConsolidation(facts)+managerResults()+cards([['Receita gross',t.gross,n(t.gross)*n(data.fx),'Seleção atual'],['Mídia',Math.abs(n(t.spend)),Math.abs(n(t.spend))*n(data.fx),'Contas vinculadas'],['Resultado operacional',t.profit,n(t.profit)*n(data.fx),'Antes das despesas do site e gerais',true],['Receita líquida',t.net,n(t.net)*n(data.fx),'Após inválidos e rev share']])+result;}
return result;}
function admin(){return '<div class="admin-cards">'+[['sites','Cadastro de sites','Sites e status do mês; o rateio acompanha os ativos.'],['company','Despesas da empresa','Lançamentos, valores, status e despesas extras.'],['personnel','Funcionários','Remuneração calculada e pagamentos sob seu controle.'],['rates','Câmbio e inválidos','Cotações provisórias e valores confirmados no pagamento.']].map(([v,t,s])=>`<button class="admincard" data-view="${v}"><span>${v==='rates'?'↔':v==='company'?'▤':'◎'}</span><h2>${t}</h2><p>${s}</p><small>Abrir →</small></button>`).join('')+'</div><div class="rule-note">Configurações e lançamentos de Agosto 2026. Setembro ainda não está aberto: não reutilize os valores de agosto para outro mês. Sites/status e percentuais são gravados no mês selecionado, com histórico. Área restrita à conta de Rodolfo.</div>';}
function siteView(){const sites=data.sites||[],active=sites.filter(s=>s.status==='ATIVO').reduce((a,s)=>a+s.units,0);return panel('Cadastro de sites · Agosto 2026',`${sites.length} sites · ${active} cotas ativas · alteração aplicada ao mês inteiro`,table(['Site / domínio','Status','Cotas de rateio','Países','Gestor / vínculo','Ações'],sites.map(s=>[esc(s.name),`<span class="pill ${s.status==='ATIVO'?'good':'warn'}">${esc(s.status)}</span>`,esc(s.units),esc(s.countries.join(' · ')),esc(managerLabel(s.manager)),`<button class="smallbutton" data-site-edit="${esc(s.id)}">Editar status</button>`]))+'<div class="summary-note">Preservamos as cotas da planilha: Openzed e Infinitynexx têm dois blocos financeiros cada. Inativar um site retira suas cotas da divisão, mas não apaga receitas ou gastos já lançados. Um novo site começa com uma cota e sem receitas/gastos. Despesas da empresa, rateio e remunerações vinculadas são recalculados. Nenhuma alteração é enviada ao Sheets.</div>', '<button id="addSite">+ Cadastrar site</button>');}
function siteEditor(id){const s=(data.sites||[]).find(x=>x.id===id);const body=s?`<p><strong>${esc(s.name)}</strong> · Agosto 2026 · ${s.units} cota(s)</p><label>Status<select id="siteStatus"><option ${s.status==='ATIVO'?'selected':''}>ATIVO</option><option ${s.status==='INATIVO'?'selected':''}>INATIVO</option></select></label>`:`<div class="formgrid"><label class="wide">Nome / domínio do site<input id="siteName" required maxlength="100"></label><label>Países (separados por vírgula)<input id="siteCountries" required placeholder="US, BR"></label><label>Status<select id="siteStatus"><option>ATIVO</option><option>INATIVO</option></select></label><label>Gestor<select id="siteManager" required><option value="">Selecione</option>${['joe','nicolas','kelly','isliago','george','SEM_COMISSAO'].map(m=>`<option>${m}</option>`).join('')}</select></label><label>Parceiro<select id="sitePartner" required><option value="">Selecione</option>${['ActiveView','JBF','M2','YMonetize'].map(v=>`<option>${v}</option>`).join('')}</select></label><label>Moeda da receita<select id="siteCurrency">${['USD','CAD','GBP','BRL'].map(v=>`<option>${v}</option>`).join('')}</select></label></div>`;
 openEditor(s?'Status do site · Agosto 2026':'Cadastrar site · Agosto 2026',body+'<div class="rule-note">Vale para o mês inteiro de agosto, não para setembro. O rateio entre ativos e as remunerações vinculadas serão recalculados. Histórico de receitas/gastos permanece preservado.</div>',async()=>{const payload={target:s?.id||null,status:$('#siteStatus').value};if(!s)Object.assign(payload,{name:$('#siteName').value,countries:$('#siteCountries').value.split(',').map(x=>x.trim().toUpperCase()),manager:$('#siteManager').value,partner:$('#sitePartner').value,currency:$('#siteCurrency').value});await save('sites',payload);},'Salvar e recalcular');
}
function expenseView(category){const all=data.domain.expenses.filter(e=>e.category===category&&e.label);const rows=all.filter(e=>!e.archived);const total=rows.reduce((s,e)=>s+n(e.usd),0);const title=category==='company'?'Despesas da empresa':'Despesas dos funcionários';const actions=`<button id="addExpense">+ ${category==='company'?'Despesa extra':'Despesa de funcionário'}</button>`;
return panel(title,`Acesso restrito · ${rows.length} lançamentos · total ${fmt(Math.abs(total))} / ${fmt(Math.abs(total)*n(data.fx),'BRL')}`,`<div class="filters"><div class="search"><input id="expenseSearch" aria-label="Buscar despesa" placeholder="Buscar ${category==='company'?'despesa':'gestor ou funcionário'}…"></div></div>`+table([category==='company'?'Despesa Tipo':'Gestor','Valor $','Valor R$','Status','Data da conferência','Ações'],rows.map(e=>[`<span>${esc(e.label)}</span><span class="subline">${e.mode==='COMMISSION_FLOOR'?'Remuneração automática · fórmula do gestor':e.extra?'Despesa extra':e.edited?'Valor ajustado na dash':'Despesa da planilha'}</span>`,fmt(Math.abs(n(e.usd))),fmt(Math.abs(n(e.brl)),'BRL'),reviewBadge(e),esc(reviewDate(e.checked_on)),`<button class="smallbutton" data-expense="${esc(e.id)}">Editar</button> <button class="smallbutton danger" data-archive="${esc(e.id)}">Excluir</button>`]))+`<div class="summary-note">${category==='personnel'?'As comissões seguem os resultados dos gestores. Editar o status não altera a remuneração calculada; valores extras ficam separados.':'Valores positivos nesta lista representam despesas; o resumo faz a dedução.'} Exclusão retira o lançamento do mês da dash, preservando o histórico e a planilha.</div>${all.some(e=>e.archived)?'<div class="panelbody"><details><summary>Despesas excluídas · histórico preservado</summary>'+all.filter(e=>e.archived).map(e=>`<div class="histrow">${esc(e.label)} <button class="smallbutton" data-restore="${esc(e.id)}">Restaurar</button></div>`).join('')+'</details></div>':''}`,actions);}
function rateView(){const time=data.quote_sync?new Date(data.quote_sync).toLocaleString('pt-BR'):'Ainda não sincronizado';return panel('Câmbio, inválidos e percentuais',monthLabel()+' · alterações exclusivas deste mês',`<div class="filterbar"><label>Mês de referência<select data-period-control aria-label="Mês dos parâmetros">${$('#period').innerHTML}</select></label></div><div data-monthly-rates>${table(['Parâmetro','Valor','Modo','Conferência','Origem','Ações'],data.rates.map(r=>[esc(r.label),esc(ratePercent(r)?percent(r.value):dec(r.value)),r.mode==='auto'?'Automático':'Manual',r.status==='confirmed'?'Confirmado':'Provisório',esc(r.source),`<button class="smallbutton" data-rate="${esc(r.key)}">Editar</button>`]))}</div><div class="summary-note">Cotações, inválidos, imposto e revshare pertencem ao mês acima. Alterar setembro não modifica agosto. Valores automáticos acompanham a fonte até serem fixados; YMonetize inativo permanece manual. A exceção de revshare M2 (EW82) é preservada. Última leitura Google: ${esc(time)}.</div>`);}
function accountView(){const list=accountData.accounts.filter(a=>normalize(a.name+' '+a.id+' '+a.sites.join(' ')).includes(normalize(accountSearch))).sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));const pending=accountData.slots.filter(s=>['not_found','ambiguous','currency_conflict'].includes(s.state));return panel('Cadastro de contas de anúncio',`${accountData.accounts.length} contas · vínculos de ${monthLabel()}`,`<div class="filterbar"><input id="accountSearch" aria-label="Buscar conta" placeholder="Nome, ID ou site…" value="${esc(accountSearch)}"></div><div data-account-table>${table(['Nome da conta','ID','Moeda','Sites neste mês','Origem','Ações'],list.map(a=>[esc(a.name),esc(a.id),esc(a.currency),esc(a.sites.join(' · ')||'Sem vínculo neste mês'),a.verified?'Conferida com a BM':'Cadastro local',`<button class="smallbutton" data-account-edit="${esc(a.id)}">Editar</button>`]))}</div><div class="summary-note">Nome e ID identificam a conta. Os sites são escolhidos por mês. Alterações aqui não modificam contas ou campanhas na Meta. Campos genéricos vazios foram retirados; lançamentos existentes são preservados.</div>${pending.length?`<details class="account-pending"><summary>${pending.length} posições da origem aguardam identificação segura</summary>${pending.map(s=>`<p><strong>${esc(s.sheet_name)}</strong> · ${esc(s.sites.join(' · '))} · ${esc(s.countries.join(' · '))}<br><small>${s.state==='ambiguous'?'Nome ambíguo':s.state==='currency_conflict'?'Moeda divergente':'Sem correspondência inequívoca no inventário da BM'}. Os valores da origem permanecem preservados.</small></p>`).join('')}</details>`:''}`,`<button id="addAccount">+ Nova conta</button>`);}
function accountEditor(id){const a=accountData.accounts.find(a=>a.id===id),existing=new Set(accountData.accounts.map(a=>a.id));openEditor(a?'Editar conta de anúncio':'Cadastrar conta de anúncio',`<div class="info-strip">${esc(monthLabel())} · vínculo de sites exclusivo deste mês. O ID e a moeda de uma conta já usada não são alterados.</div>${!a?`<label>Preencher pelo inventário da BM (opcional)<select name="candidate"><option value="">Cadastro manual</option>${accountData.candidates.filter(c=>!existing.has(c.account_id)).map(c=>`<option value="${esc(c.account_id)}">${esc(c.name)} · ${esc(c.account_id)}</option>`).join('')}</select></label>`:''}<label>Nome da conta<input name="name" maxlength="150" value="${esc(a?.name||'')}" required></label><div class="formgrid"><label>ID da conta<input name="id" inputmode="numeric" pattern="[0-9]+" value="${esc(a?.id||'')}" ${a?'readonly':''} required></label><label>Moeda<select name="currency" ${a?'disabled':''}>${['USD','BRL','CAD','GBP'].map(c=>`<option ${c===a?.currency?'selected':''}>${c}</option>`).join('')}</select></label></div><label>Sites em que veicula neste mês<select name="sites" multiple size="5" required>${data.sites.map(s=>`<option value="${esc(s.name)}" ${a?.sites.includes(s.name)?'selected':''}>${esc(s.name)} · ${esc(s.status)}</option>`).join('')}</select></label><p class="fieldhelp">Escolha na lista; mais de um site pode ser selecionado quando a conta é compartilhada.</p>`,async()=>{const form=$('#editorForm'),fd=new FormData(form),payload={id:fd.get('id'),name:fd.get('name'),currency:form.elements.currency.value,sites:fd.getAll('sites'),edit:!!a,period:currentPeriod,revision:accountData.revision};await writable();await api('/api/ad-accounts',payload);await reload();const after=accountData.accounts.find(x=>x.id===payload.id);if(!after||after.name!==payload.name||JSON.stringify([...after.sites].sort())!==JSON.stringify([...payload.sites].sort()))throw Error('O cadastro não confirmou o readback');message('Conta salva e conferida.');},'Salvar conta');const select=$('#editorForm [name="candidate"]');if(select)select.onchange=()=>{const c=accountData.candidates.find(a=>a.account_id===select.value);if(c){const f=$('#editorForm');f.elements.name.value=c.name;f.elements.id.value=c.account_id;f.elements.currency.value=c.currency;}};}

function render(){if(!data)return;const state=data.domain.projection?.state||'closed';$('.context-note span').textContent=monthLabel()+(state==='planned'?' · Período futuro, sem resultados herdados. Cadastros e parâmetros iniciais; despesas precisam de lançamento.':state==='closed'?' · Período encerrado; câmbio e inválidos podem aguardar liquidação.':' · Em andamento. Resultado provisório; confira receitas, gastos e despesas do mês.');const texts={overview:['Resumo financeiro','RESULTADO DA EMPRESA','O mês inteiro, sem perder o detalhe.'],movement:[selectedSite||'Movimento do mês','CONSULTA E LANÇAMENTOS','Busque um domínio. Consulte os dias. Atualize receitas e gastos.'],admin:['Administrativo','ACESSO RESTRITO','Despesas, remunerações e parâmetros financeiros.'],company:['Despesas da empresa','ADMINISTRATIVO','Consulte, inclua e ajuste seus lançamentos.'],personnel:['Funcionários','ADMINISTRATIVO','Remuneração automática, pagamentos e despesas extras.'],accounts:['Contas de anúncio','ADMINISTRATIVO','Identidade da conta e sites vinculados neste mês.'],sites:['Cadastro de sites','ADMINISTRATIVO','Status e rateio por site no mês selecionado.'],rates:['Câmbio, imposto e revshare','ADMINISTRATIVO','Valores provisórios até a confirmação da empresa.']};const [title,eye,sub]=texts[view];$('#title').textContent=title;$('#eyebrow').textContent=eye;$('#subtitle').textContent=sub+' · '+(data.period?.label||'Agosto 2026');const isAdmin=['admin','company','personnel','rates','sites','accounts'].includes(view);$('#adminNav').hidden=!isAdmin;$('#nav [data-view="admin"]').setAttribute('aria-expanded',String(isAdmin));$$('#nav button').forEach(b=>b.classList.toggle('selected',b.dataset.view===view));$('#content').innerHTML=view==='overview'?overview():view==='movement'?movement():view==='admin'?admin():view==='rates'?rateView():view==='sites'?siteView():view==='accounts'?accountView():expenseView(view==='company'?'company':'personnel');$$('[data-width]').forEach(e=>e.style.width=e.dataset.width+'%');bindView();}
function navigate(v){if(v==='movement'){selectedSite='';search='';country='';manager='';day='';}view=v;pageIndex=0;message('');render();window.scrollTo({top:0});}
function openEditor(title,body,handler,button='Salvar alterações'){if(switching)return;$('#editor').dataset.period=currentPeriod;submitHandler=handler;$('#editorTitle').textContent=title;$('#editorBody').innerHTML=body;$('#save').textContent=button;$('#dialogError').textContent='';$('#editor').showModal();}
function editFact(id){const f=data.domain.facts.find(x=>x.id===id),mapping=data.model.facts[id];if(f?.native_placeholder&&!mapping)return newEntry(f);if(!mapping){const a=data.additions.find(x=>x.id===id&&!x.kind);if(!a){message('Origem não encontrada.',true);return;}openEditor('Editar lançamento extra',`<p class="muted">${esc(a.site)} · ${esc(a.country)} · ${esc(a.date)} · ${esc(a.manager)}</p><div class="formgrid"><label>Receita · ${esc(a.currency)}<input id="nativeGross" required inputmode="decimal" value="${esc(a.gross)}"></label><label>Gasto · USD<input id="nativeSpend" required inputmode="decimal" value="${esc(a.spend)}"></label></div>`,async()=>save('entry-values',{entry_id:id,gross:numberInput($('#nativeGross').value),spend:numberInput($('#nativeSpend').value)}),'Salvar e recalcular');return;}const allKeys=[...new Set([...mapping.gross,...mapping.spend])];const original={};const body=`<p class="muted">${esc(f.site)} · ${esc(f.date)} · ${esc(f.country)}. Altere somente os valores necessários. As contas abaixo são as entradas que compõem este dia.</p>`+['gross','spend'].map(k=>`<div class="editgroup"><h3>${k==='gross'?'Receitas de origem':'Gastos das contas de anúncio'}</h3>${mapping[k].map(key=>{const x=data.model.inputs[key];original[key]=String(x.value);return `<div class="inputrow"><label for="input-${esc(key)}">${esc(x.label)}<small>${esc(managerLabel(x.managers.join(' / ')||f.manager))} · ${esc(inputCurrency(x,f))} · ${esc(x.source)}</small></label><input id="input-${esc(key)}" data-input-key="${esc(key)}" aria-label="${esc(k+' '+x.source)}" inputmode="decimal" value="${esc(x.value===''?'':String(x.value).replace('.',','))}" placeholder="Sem lançamento"></div>`;}).join('')}</div>`).join('')+'<div class="rule-note">Receitas seguem a moeda indicada. Gastos seguem a moeda da conta na origem. Somente entradas são editadas; fórmulas, datas e vínculos permanecem protegidos.</div>';
openEditor('Editar movimento do dia',body,async()=>{const changes=allKeys.map(key=>({key,value:numberInput($(`[data-input-key="${CSS.escape(key)}"]`).value)})).filter(c=>c.value!==original[c.key]&&!(c.value!==''&&original[c.key]!==''&&n(c.value)===n(original[c.key])));if(!changes.length)throw Error('Nenhum valor foi alterado.');if(changes.some(c=>c.value===''))throw Error('Para zerar uma entrada existente, informe 0. Campos não alterados permanecem vazios.');await save('ui-inputs',{changes});},'Salvar e recalcular');}
function expenseEditor(id,archive=false,restore=false){
 const category=view==='company'?'company':'personnel',e=id?data.domain.expenses.find(x=>x.id===id):null,automatic=e?.mode==='COMMISSION_FLOOR';
 const status=reviewStatus(e||{})==='Conferido'?'Conferido':'A conferir';
 const body=archive?`<p>Excluir <strong>${esc(e.label)}</strong> do mês da dash?</p><div class="rule-note">O valor deixa de ser descontado do resultado. Histórico e planilha são preservados; a exclusão pode ser restaurada.</div>`:`<div class="formgrid"><label class="wide">${category==='company'?'Despesa Tipo':'Gestor / funcionário'}<input id="expenseLabel" maxlength="150" required value="${esc(e?.label||'')}"></label>${automatic?'<div class="rule-note wide">Remuneração calculada automaticamente a partir do resultado do gestor. O valor não pode ser sobrescrito neste formulário. Para um extra, crie uma despesa separada.</div>':`<label>Valor<input id="expenseAmount" inputmode="decimal" required value="${esc(e?n(e.edit_amount??Math.abs(n(e.archived_usd??e.usd))):'')}"></label><label>Moeda<select id="expenseCurrency"><option value="USD" ${e?.edit_currency==='USD'?'selected':''}>Dólar · $</option><option value="BRL" ${e?.edit_currency==='BRL'?'selected':''}>Real · R$</option></select></label>`}<label>Status<select id="expenseStatus">${['A conferir','Conferido'].map(s=>`<option ${s===status?'selected':''}>${s}</option>`).join('')}</select></label><label id="expenseDateField" ${status==='Conferido'?'':'hidden'}>Data da conferência<input id="expenseCheckedOn" type="date" value="${esc(e?.checked_on||'')}" ${status==='Conferido'?'required':'disabled'}></label></div>`;
 openEditor(archive?'Excluir despesa':restore?'Restaurar despesa':e?'Editar despesa':'Adicionar despesa extra',body,async()=>{
  const body={category:e?.category||category,target:e?.id||null,label:archive?e.label:$('#expenseLabel').value,status:archive?e.status||'Não informado':$('#expenseStatus').value,checked_on:archive?e.checked_on||null:$('#expenseStatus').value==='Conferido'?$('#expenseCheckedOn').value:null,archived:archive};
  if(!automatic&&!archive){body.amount=numberInput($('#expenseAmount').value);body.currency=$('#expenseCurrency').value;}
  await save('expenses',body);
 },archive?'Excluir do mês':restore?'Restaurar e recalcular':'Salvar e recalcular');
 if(!archive)$('#expenseStatus').onchange=()=>{const checked=$('#expenseStatus').value==='Conferido';$('#expenseDateField').hidden=!checked;$('#expenseCheckedOn').required=checked;$('#expenseCheckedOn').disabled=!checked;};
}
const ratePercent=r=>['invalid','percent'].includes(r.type);
function rateEditor(key){const r=data.rates.find(x=>x.key===key);openEditor(r.label,`<div class="formgrid">${r.automatic?`<label class="wide">Atualização<select id="rateMode"><option value="auto" ${r.mode==='auto'?'selected':''}>Automático · acompanhar GOOGLEFINANCE</option><option value="fixed" ${r.mode==='fixed'?'selected':''}>Fixo · informar taxa efetiva do pagamento</option></select></label>`:'<input type="hidden" id="rateMode" value="fixed">'}<label>${ratePercent(r)?'Percentual (%)':'Valor efetivo'}<input id="rateValue" inputmode="decimal" required value="${esc(String(ratePercent(r)?n(r.value)*100:r.value).replace('.',','))}"></label><label>Confirmação<select id="rateStatus"><option value="provisional" ${r.status==='provisional'?'selected':''}>Provisório</option><option value="confirmed" ${r.status==='confirmed'?'selected':''}>Confirmado no pagamento</option></select></label></div><div class="rule-note">${ratePercent(r)?'Digite o percentual do demonstrativo (ex.: 0,5772 para 0,5772%). Não é uma confirmação automática da média anterior.':'Ao fixar uma taxa, a sincronização deixa de substituí-la. Voltar para automático exige escolher essa opção explicitamente.'}</div>`,async()=>{const mode=$('#rateMode').value;let value=numberInput($('#rateValue').value);if(ratePercent(r)){if(!/^\d+(\.\d{1,8})?$/.test(value))throw Error('Percentual inválido. Use até 8 casas decimais.');const [a,b='']=value.split('.');const padded=a.padStart(3,'0');value=padded.slice(0,-2)+'.'+padded.slice(-2)+b;}await save('rates',{key,mode,value,status:$('#rateStatus').value});},'Salvar e recalcular');}
function newEntry(reference){const f=reference?.native_placeholder?reference:data.domain.facts.find(x=>x.site===selectedSite)||data.domain.facts[0];const registration=(data.sites||[]).find(s=>s.name===selectedSite);openEditor('Lançamento extra de receita e mídia',`<p class="muted">Adiciona valores ao mês. Para corrigir um lançamento existente, use Editar dia, evitando duplicação.</p><div class="formgrid"><label>Site<input name="site" required value="${esc(selectedSite)}"></label><label>Parceiro<input name="partner" required value="${esc(f.partner)}"></label><label>Gestor<select name="manager" required><option value="">Selecione</option>${['joe','nicolas','kelly','isliago','george','SEM_COMISSAO'].map(v=>`<option ${f.native_placeholder&&v===f.manager?'selected':''}>${v}</option>`).join('')}</select></label><label>País<input name="country" required maxlength="2" pattern="[A-Z]{2}" value="${esc(country||f.country)}"></label><label>Data<input name="date" type="date" min="${esc(currentPeriod)}-01" max="${esc(currentPeriod)}-${data.period?.days||31}" value="${esc(f.native_placeholder?f.date:currentPeriod+'-01')}" required></label><label>Moeda da receita<select name="currency">${['USD','CAD','GBP','BRL'].map(c=>`<option ${c===registration?.currency?'selected':''}>${c}</option>`).join('')}</select></label><label>Receita bruta<input name="gross" required inputmode="decimal"></label><label>Gasto em USD (positivo)<input name="spend" required inputmode="decimal"></label>${[['invalid_rate','Inválidos (fração)',f.invalid_rate],['share_rate','Rev share (fração)',f.share_rate],['tax_rate','Imposto (fração)',f.tax_rate],['USDBRL','USD / BRL',data.fx],['USDCAD','USD / CAD',data.rates.find(x=>x.source==='H1').value],['GBPUSD','GBP / USD',data.rates.find(x=>x.source==='I1').value]].map(([k,l,v])=>`<label>${l}<input name="${k}" required value="${esc(v)}" inputmode="decimal" ${registration?.new?'readonly':''}></label>`).join('')}</div><div class="rule-note">${registration?.new?'Site cadastrado: câmbio, imposto, revshare e inválidos seguem os parâmetros do mês; exceção M2 preservada.':'Confira as taxas deste lançamento extra.'} Não há captura automática de reports GAM, Facebook ou Google nesta tela.</div>`,async()=>{const values=Object.fromEntries(new FormData($('#editorForm')));for(const k of ['gross','spend','invalid_rate','share_rate','tax_rate','USDBRL','USDCAD','GBPUSD'])values[k]=numberInput(values[k]);values.quotes={USDBRL:values.USDBRL,USDCAD:values.USDCAD,GBPUSD:values.GBPUSD};await save('entries',values);},'Adicionar e recalcular');}
function bindView(){for(const select of $$('[data-period-control]'))select.onchange=()=>{$('#period').value=select.value;$('#period').dispatchEvent(new Event('change'));};if($('#addAccount'))$('#addAccount').onclick=()=>accountEditor();if($('#accountSearch'))$('#accountSearch').oninput=e=>{accountSearch=e.target.value;const pos=e.target.selectionStart;render();$('#accountSearch').focus();$('#accountSearch').setSelectionRange(pos,pos);};if($('#addSite'))$('#addSite').onclick=()=>siteEditor();if($('#siteSearch'))$('#siteSearch').oninput=e=>{search=e.target.value;selectedSite='';pageIndex=0;const pos=e.target.selectionStart;render();$('#siteSearch').focus();$('#siteSearch').setSelectionRange(pos,pos);};if($('#countryFilter'))$('#countryFilter').onchange=e=>{country=e.target.value;pageIndex=0;render();};if($('#managerFilter'))$('#managerFilter').onchange=e=>{manager=e.target.value;pageIndex=0;render();};if($('#dayFilter'))$('#dayFilter').onchange=e=>{day=e.target.value;pageIndex=0;render();};if($('#backSites'))$('#backSites').onclick=()=>{selectedSite='';day='';search='';pageIndex=0;render();};if($('#prev'))$('#prev').onclick=()=>{pageIndex--;render();};if($('#next'))$('#next').onclick=()=>{pageIndex++;render();};if($('#expenseSearch'))$('#expenseSearch').oninput=e=>{$$('#content tbody tr').forEach(tr=>tr.hidden=!normalize(tr.textContent).includes(normalize(e.target.value)));};if($('#addExpense'))$('#addExpense').onclick=()=>expenseEditor();if($('#newEntry'))$('#newEntry').onclick=newEntry;}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||busy)return;if(b.dataset.jumpCountry){const block=$(`.country-block[data-country="${CSS.escape(b.dataset.jumpCountry)}"]`);if(block){block.open=true;block.querySelector('summary').focus({preventScroll:true});block.scrollIntoView({behavior:'smooth',block:'start'});}return;}if(busy||switching)return;if(b.dataset.accountEdit)accountEditor(b.dataset.accountEdit);if(b.dataset.siteEdit)siteEditor(b.dataset.siteEdit);if(b.dataset.view)navigate(b.dataset.view);if(b.dataset.site){selectedSite=b.dataset.site;search='';country='';manager='';day='';view='movement';pageIndex=0;render();window.scrollTo({top:0});}if(b.dataset.currency){currency=b.dataset.currency;render();}if(b.dataset.editFact)editFact(b.dataset.editFact);if(b.dataset.expense)expenseEditor(b.dataset.expense);if(b.dataset.archive)expenseEditor(b.dataset.archive,true);if(b.dataset.restore)expenseEditor(b.dataset.restore,false,true);if(b.dataset.rate)rateEditor(b.dataset.rate);if(b.hasAttribute('data-close'))$('#editor').close();});
$('#editorForm').onsubmit=async e=>{e.preventDefault();if(busy)return;busy=true;$('#save').disabled=true;$('#dialogError').textContent='Salvando e recalculando…';try{await submitHandler();$('#editor').close();}catch(error){$('#dialogError').textContent=error.message;}finally{busy=false;$('#save').disabled=false;}};
$('#editor').addEventListener('cancel',e=>{if(busy)e.preventDefault();});
$('#period').onchange=async e=>{const requested=e.target.value;if(busy||switching||$('#editor').open){e.target.value=currentPeriod;message('Conclua ou cancele a edição antes de trocar o mês.',true);return;}switching=true;$('#content').inert=true;$('#nav').inert=true;e.target.disabled=true;try{await reload(requested);}catch(error){e.target.value=currentPeriod;message(error.message,true);}finally{switching=false;$('#content').inert=false;$('#nav').inert=false;e.target.disabled=false;for(const s of $$('[data-period-control]'))s.value=currentPeriod;}};
$('#refresh').onclick=()=>reload().catch(e=>message(e.message,true));
$('#logout').onclick=$('#logoutMobile').onclick=async()=>{await api('/api/auth/logout',{});location.replace('/login');};
$('#history').onclick=async()=>{try{const rows=await api('/api/scenarios/'+data.id+'/audit');openEditor('Histórico de alterações',rows.map(r=>`<div class="histrow"><strong>${esc(({AUTO_QUOTES_UPDATED:'Cotação automática atualizada',DAILY_INPUTS_CHANGED:'Receitas ou gastos alterados',EXPENSE_ADDED:'Despesa adicionada',EXPENSE_UPDATED:'Despesa atualizada',EXPENSE_ARCHIVED:'Despesa excluída do mês',FINANCIAL_RATE_CHANGED:'Câmbio ou inválidos alterados',WORKSPACE_CREATED:'Mês de trabalho iniciado',IMPORT_VERIFIED:'Dados de referência carregados'})[r.action]||r.action)}</strong><small>${esc(new Date(r.created_at).toLocaleString('pt-BR'))} · ${esc(r.actor)}</small></div>`).join('')||'<p>Nenhuma alteração neste mês.</p>',async()=>{},'Fechar');}catch(e){message(e.message,true);}};
api('/api/auth/me').then(async u=>{csrf=u.csrf;await reload();}).catch(e=>message(e.message,true));
setInterval(()=>{if(!busy&&!$('#editor').open)reload().catch(e=>message('Não foi possível atualizar. Os últimos dados permanecem visíveis.',true));},300000);
